package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for SimpleType.construct(Class<?> cls)
 */
public class SimpleType_construct_TriageGen2Test {

    @Test
    public void testConstruct_WithValidClass() {
        Class<?> validClass = String.class;
        SimpleType result = SimpleType.construct(validClass);

        assertNotNull("Result should not be null", result);
        assertEquals("The class should match the input class", validClass, result.getRawClass());
    }

    @Test
    public void testConstruct_WithIntegerClass() {
        Class<?> validClass = Integer.class;
        SimpleType result = SimpleType.construct(validClass);

        assertNotNull(result);
        assertEquals(Integer.class, result.getRawClass());
    }

    @Test
    public void testConstruct_WithMapThrowsException() {
        // Test Map.class directly
        IllegalArgumentException exception1 = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(Map.class);
        });
        assertEquals("Can not construct SimpleType for a Map (class: java.util.Map)", exception1.getMessage());

        // Test a subclass of Map
        IllegalArgumentException exception2 = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(HashMap.class);
        });
        assertEquals("Can not construct SimpleType for a Map (class: java.util.HashMap)", exception2.getMessage());
    }

    @Test
    public void testConstruct_WithCollectionThrowsException() {
        // Test Collection.class directly
        IllegalArgumentException exception1 = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(java.util.Collection.class);
        });
        assertEquals("Can not construct SimpleType for a Collection (class: java.util.Collection)", exception1.getMessage());

        // Test a subclass of Collection
        IllegalArgumentException exception2 = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(ArrayList.class);
        });
        assertEquals("Can not construct SimpleType for a Collection (class: java.util.ArrayList)", exception2.getMessage());
    }

    @Test
    public void testConstruct_WithArrayThrowsException() {
        // Test String array
        IllegalArgumentException exception1 = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(String[].class);
        });
        assertEquals("Can not construct SimpleType for an array (class: [Ljava.lang.String;)", exception1.getMessage());

        // Test primitive array
        IllegalArgumentException exception2 = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(int[].class);
        });
        assertEquals("Can not construct SimpleType for an array (class: [I)", exception2.getMessage());
    }

    @Test
    public void testConstruct_WithListSubclass() {
        // List is a Collection, should throw exception
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(List.class);
        });
        assertEquals("Can not construct SimpleType for a Collection (class: java.util.List)", exception.getMessage());
    }
}
